window.TEXTP = window.TEXTP || {};
window.TEXTP["92.3"] = [[["p","199/10 – Второй аят:"],["p","Всевышний Аллах сказал: «А разведенные (женщины, у которых бывают месячные) выжидают [обязаны ждать] (после развода, не выходя замуж за другого и удерживая) самих себя (от такого замужества) три периода [либо три месячных, либо три чистых периода] (чтобы удостовериться в том, что они не беременны), и не разрешается им [разведённым женщинам] скрывать то, что сотворил Аллах в их утробах [есть ли беременность или когда происходят месячные], если они [эти женщины] (истинно) веруют в Аллаха и в Последний День. А мужья их имеют больше прав вернуть их [разведённую жену] при этом [при ‘идде – послеразводном сроке], если они желают уладить (отношения) [снова объединиться, а не для причинения вреда жене с целью наказания]. И у них [у женщин, как разведенных, так и неразведённых] – то же самое [есть такие же права], что и (обязанности возложенные) на них [женщинах], согласно принятому (по установлению Аллаха). А мужья имеют над ними [жёнами] – степень [обязанность обеспечивать жену и право дать развод]. А Аллах – величественный (в Своём владычестве), мудрый (в Своих решениях и повелениях)! (228) (Возвратный) развод (может даваться только) два раза: (после него) [возвратного развода] – либо удержание (жены у себя) [возврат её], согласно принятому (у людей), либо отпустить с благодеянием [соблюдая её права и не причиняя ей вреда]. И не дозволяется вам (о, мужья) брать хоть что-либо из того, что вы им [жёнам] даровали (как например брачный дар и подобное этому), кроме, как только если они оба (супруга) (будут) бояться не выполнить ограничений Аллаха (в вопросах соблюдения супружеских прав). (И в таком случае оба супруга представляют свою ситуацию ответственным лицам или людям, которые могут помочь разрешить её). А если вы [ответственные лица] боитесь, что они оба [супруг и супруга] не выполнят ограничений Аллаха, то не будет греха на них [на муже и жене] в том, чем она [супруга] себя выкупит [дозволяется женщине предложить мужу определённое имущество в обмен на развод]. Таковы границы Аллаха [обязательные установления] (которые отделяют дозволенное от запретного), не преступайте же их [границы], а если кто преступает границы Аллаха, те – злодеи (по отношению к самим себе). (229) Если же он [муж] дал ей развод (в третий раз), то она не дозволяется ему после этого, пока она не выйдет замуж за другого (мужчину). (230)», сура «Аль-Бакара»/228-230 аяты."],["sc","img/word-92/image79.webp",296,512,"f"],["c","Книга Развода"],["h2","<b>Глава: О клятве не иметь супружеской близости с женой</b>"]],[["p","200/11 – Первый аят:"],["p","Всевышний Аллах сказал: «Тем, которые поклянутся о своих женах, [те, которые поклянутся Аллахом, что не будут иметь близости с женами] – (для них обязательно) выжидание четырех месяцев. И если они возвратятся (до истечения четырех месяцев [совершат близость] с намерением продолжить семейную жизнь), то, поистине, Аллах прощающий (то, что случилось с ними из-за клятвы), милосердный (к ним)! (226) А если они [мужья] решатся на развод (и продолжат удерживаться от близости по своей клятве), то, поистине, Аллах – слышащий (речи), знающий (намерения)! (227)», сура «Аль-Бакара»/226-227 аяты."],["h2","<b>Глава: Об объявлении своей жены матерью (Аз-Зихар)</b>"],["p","201/12 – Первый аят:"],["p","Всевышний Аллах сказал: «Те из вас, которые своим жёнам говорят, что они [жёны] подобны спинам их матерей [матерей мужей], (совершают грех, так как) они [их жёны] (в действительности) не матери им [своим мужьям], ведь их матери [матери мужей] – только те, которые родили их, – те, однозначно, говорят порицаемые речи и ложь. А ведь Аллах – действительно, снисходительный и прощающий (по отношеню к тем, которые после совершения греха, совершают искреннее покаяние)! (2) И те (мужья), которые говорят своим жёнам, что они [жёны] подобны спинам их матерей и потом отрекаются от того, что сказали [решаются продолжить супружескую жизнь], (то на них лежит обязанность исполнить искупление за этот грех, а это) – освобождение (верующего) раба (или верующей рабыни), прежде чем они [супруги] коснутся друг друга [будут иметь близость]. Это [такое решение Аллаха] – то, чем вас (о, верующие) увещают (чтобы вы не совершали подобного), и Аллах ведает о том, что вы совершаете! (3) А кто не найдёт (раба для освобождения) – то (будет обязан соблюдать) пост (в течении) двух месяцев последовательных [без перерыва], прежде чем они [супруги] коснутся друг друга [будут иметь близость]. А кто не может (соблюдать и пост), то (будет обязан) накормить (досыта) шестьдесят бедняков. Это [разъяснение для вас решения Аллаха об этом] для того, чтобы вы верили в Аллаха и Его посланника. Это [упомянутые положения] (являются) ограничениями Аллаха (4)», сура «Аль-Муджадиля»/2-4 аяты."],["h2","<b>Глава: Клятвенное заверение</b>"],["p","202/13 – Первый аят:"],["p","Всевышний Аллах сказал: «А те, которые бросают (обвинение в совершении прелюбодеяния) в своих жён и у них нет свидетелей, кроме самих себя,"],["sc","img/word-92/image80.webp",302,504,"f"]],[["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","то свидетельство каждого из них (у шариатского судьи) – четыре(3) свидетельства Аллахом, что он [муж] правдив (в обвинении своей жены в совершении прелюбодеяния), (6) а пятое, – что проклятие Аллаха (будет) на нём [на муже], если он из числа лжецов. (7) И отклоняется от неё [от жены] наказание [побиение камнями до смерти], если она засвидетельствует четырьмя свидетельствами Аллахом, что он [её муж] однозначно из числа лжецов, (8) и пятое, – что гнев Аллаха (будет) на ней, если он из числа правдивых [говорит правду] (9)», сура «Ан-Нур»/6-9 аяты."],["sep",""],["sc","img/word-92/image81.webp",295,503,"f"],["c","Книга Сроков выжидания"],["h2","<b>Книга Сроков выжидания (1)</b>"],["p","203/1 – Первый аят:"],["p","Всевышний Аллах сказал: «О те, которые уверовали! Если вы женитесь на верующих (женщинах) [заключите с ними брачный союз], а потом разведётесь с ними раньше, чем коснётесь их [прежде чем будете иметь с ними близость], то нет для вас (о, верующие мужчины) (обязанностью) по отношению к ним [к разводимым женам] никакого (послеразводного) срока, который вы бы отсчитывали. И наделяйте их [разводимых женщин] дарами (когда разводитесь с ними) (чтобы сгладить обиду), и отпускайте их (к своим семьям) прекрасным образом [не причиняя им никакой обиды]», сура «Аль-Ахзаб»/49 аят."],["p","204/2 – Второй аят:"],["p","Всевышний Аллах сказал: «А разведенные (женщины, у которых бывают месячные) выжидают [обязаны ждать] (после развода, не выходя замуж за другого и удерживая) самих себя (от такого замужества) три периода [либо три месячных, либо три чистых периода] (чтобы удостовериться в том, что они не беременны)», сура «Аль-Бакара»/228 аят."],["p","205/3 – Третий аят:"]],[["p","Всевышний Аллах сказал: «А те, которые уже отчаялись в месячных из ваших жён [для жён в возрасте, у которых месячных уже не будет] – если вы сомневаетесь (относительно их положения), то (знайте, что) их срок – три месяца, как и для тех, у которых еще не было месячных [для слишком юных жён]. А у которых (есть) ноша [у беременных] – их (разводный) срок, чтобы они сложили свою ношу [родили]», сура «Ат-Талак»/4 аят."],["p","(1) Общее число аятов, которые привел Ибн Касим в книге Сроки выжидания – 17 аятов."],["sc","img/word-92/image82.webp",294,503,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","206/4 – Четвертый аят:"],["p","Всевышний Аллах сказал: «А те из вас (о, мужчины), которые упокоятся [умрут] и оставят жён (после своей смерти), – они [вдовы] выжидают сами с собой [не выходят замуж, не предлагают себя в жёны, не выходят из дома и не украшаются] четыре месяца и десять (дней)», сура «Аль-Бакара»/234 аят."],["h2","<b>Раздел: О соблюдении траура</b>"],["p","207/5 – Первый аят:"],["p","Всевышний Аллах сказал: «Не выгоняйте их [женщин] из их домов [где они проживают], и пусть они [женщины] (сами тоже) не выходят [пусть не покидают дом], если только они не совершат явную мерзость [как прелюбодеяние]», сура «Ат-Талак»/1 аят."],["p","208/6 – Второй аят:"],["p","Всевышний Аллах сказал: «А если они [вдовы] выйдут (по дозволенному порядку), то не (будет) греха на вас в том, что они сделают сами с собой согласно принятому», сура «Аль-Бакара»/240 аят."],["h2","<b>Глава: О завершении срока выжидания по причине родоразрешения</b>"],["p","209/7 – Первый аят:"],["p","Всевышний Аллах сказал: «А у которых (есть) ноша [у беременных] – их (разводный) срок, чтобы они сложили свою ношу [родили]», сура «Ат-Талак»/4 аят."],["sc","img/word-92/image83.webp",338,509,"f"],["c","Книга Сроков выжидания"],["h2","<b>Глава: О грудном вскармливании</b>"]],[["p","210/8 – Первый аят:"],["p","Всевышний Аллах сказал: «И ваши матери, которые вас вскормили [молочные матери], и ваши сёстры по кормлению [молочные сёстры]», сура «Ан-Ниса»/23 аят."],["h2","<b>Глава: Выплаты</b>"],["p","211/9 – Первый аят:"],["p","Всевышний Аллах сказал: «Пусть обладающий достатком расходует (на содержание бывшей жены, которая кормит для него ребёнка) из своего достатка [по мере своего богатства].  А тот, у кого удел его ограничен [он беден], то пусть он расходует из того, что дал ему Аллах [по своей возможности]. Не возлагает Аллах на душу сверх того, что Он дал ей. [Аллах не обязывает человека тратить на содержание своих иждивенцев больше, чем Он ему дал.] И Аллах устроит после тяготы облегчение [после бедности дарует богатство] (если он будет остерегаться наказания Аллаха)», сура «Ат-Талак»/7 аят."],["p","212/10- Второй аят:"],["p","Всевышний Аллах сказал: «Ведь Мы знаем, что (уже) предписали [сделали обязательным] для них [для верующих] относительно их жён [как и на скольких жениться]», сура «Аль-Ахзаб»/50 аят."],["p","213/11 – Третий аят:"],["p","Всевышний Аллах сказал: «И обходитесь с ними [с женами] достойно [с любовью, уважением и исполнением их прав]», сура «Ан-Ниса»/19 аят."],["p","214/12 – Четвертый аят:"],["p","Всевышний Аллах сказал: «Либо удержание (жены у себя) [возврат её], согласно принятому (у людей), либо отпустить с благодеянием [соблюдая её права и не причиняя ей вреда]», сура «Аль-Бакара»/229 аят."],["sc","img/word-92/image84.webp",294,504,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","215/13 – Пятый аят:"],["p","Всевышний Аллах сказал: «И у них [у женщин, как разведенных, так и неразведённых] – то же самое [есть такие же права], что и (обязанности возложенные) на них [женщинах], согласно принятому (по установлению Аллаха)», сура «Аль-Бакара»/228 аят."],["h2","<b>Раздел: О расходовании на родственников</b>"]],[["p","216/14 – Первый аят:"],["p","Всевышний Аллах сказал: «И к родителям (проявляйте искреннее) благодеяние (словами, делами, имуществом,…), и (также) к родственнику [родственникам]», сура «Ан-Ниса»/36 аят."],["p","217/15 – Второй аят:"],["p","Всевышний Аллах сказал: «А родительницы [женщины, которые родили] кормят своих детей (как мальчиков, так и девочек) полных два года; это – для того, кто захочет завершить кормление [для кормящей матери]. А на том, у кого родился [на отце ребёнка], (лежит обязанность обеспечивать) пропитанием их [разведённых кормящих жён] и одеждой согласно принятому (по шариату и среди людей). Не возлагается на душу ничего, кроме возможного для неё. [Аллах не обязывает человека делать то, что не в его возможностях.] (И) не (дозволяется) причинять вред родительнице за её ребенка и тому, у кого родился [отцу], за его ребенка. [Родителям нельзя использовать ребёнка, как средство причинения вреда друг другу.] И на наследнике (ребёнка) (лежат) те же самые (обязанности) (в случае, если отец ребёнка умрёт). А если оба они [мать и отец ребёнка] пожелают отлучения (ребёнка от груди до завершения двухлетнего срока) с (общего) согласия между ними и совета, то нет греха на них (двоих). {Отлучение ребёнка от груди по общему совету и согласию родителей делается в интересах ребёнка, то есть мать и отец ребёнка должны определить можно ли его отлучать от груди.} А если вы [родители ребёнка] пожелаете нанять кормилиц, чтобы они выкормили ваших детей, то нет греха на вас, если вы вручите [заплатите] (матери ребёнка её долю) (и нанятым кормилицам) то, что даёте согласно принятому (среди людей)», сура «Аль-Бакара»/233 аят."],["p","218/16 – Третий аят:"],["p","Всевышний Аллах сказал: «А если вы находитесь в затруднении, то будет кормить (ребёнка) для него [для отца] другая (кормилица)», сура «Ат-Талак»/6 аят."],["h2","<b>Раздел: О расходовании на тех, кто находится во владении </b>"],["p","219/17 – Первый аят:"],["p","Всевышний Аллах сказал: «Зовите их [приёмных детей] по (именам) их отцов. Это [относить родство к их отцам] – более справедливо перед Аллахом. А если же вы не знаете их отцов, тогда (они) (являются) вашими братьями по Вере и вашими близкими [сторонниками]», сура «Аль-Ахзаб»/5 аят."],["sc","img/word-92/image85.webp",296,503,"f"],["c","Книга Уголовных преступлений"],["h2","<b>Книга Уголовных преступлений (1)</b>"]],[["p","220/1 – Первый аят:"],["p","Всевышний Аллах сказал: «И не убивайте душу, которую запретил Аллах (убивать), иначе, как только по праву [как воздаяние за убийство; убийство прелюбодеев, познавших супружество; убийство вероотступника]», сура «Аль-Анам»/151 аят."],["p","221/2 – Второй аят:"],["p","Всевышний Аллах сказал: «И (никак) нельзя [запрещено] верующему убивать (другого) верующего, разве только (если это случится) по ошибке [ненамеренно: по невнимательности, неосторожности и забывчивости]. И кто (если) убьёт верующего по ошибке, то (для него, с целью искупления этого греха, становится обязательным) освобождение верующего раба и (выплата) (установленного по шариату) выкупа, (полностью) вручаемого его семье [наследникам убитого], если (только) они не сделают его как милостыню (для убившего по ошибке, простив ему этот выкуп)», сура «Ан-Ниса»/92 аят."],["p","222/3 – Третий аят:"],["p","Всевышний Аллах сказал: «А если кто убьёт верующего умышленно (и не имея на это права), то воздаянием ему (будет) Геенна [Ад], для вечного пребывания там. И разгневался Аллах на него [на намеренно убившего верующего], и проклял его [лишил Своего милосердия], и уготовал ему великое наказание!», сура «Ан-Ниса»/93 аят."],["p","(1) Общее число аятов, которые Ибн Касим привел в книге Уголовных преступлений – 8 аятов."],["sc","img/word-92/image86.webp",294,502,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Раздел: О возмездии (кысас)</b>"],["p","223/4 – Первый аят:"],["p","Всевышний Аллах сказал: «О те, которые уверовали! Предписано [сделано обязательным] вам возмездие за убитых: свободный (убивается) за свободного, и раб (убивается) за раба, и женщина (убивается) за женщину. А (если) кому-то [убийце] будет прощено что-нибудь от его брата [от убитого или его близкого], то (возмездие убийством отменяется) – согласно известному [по шариату] [убийца должен заплатить определённый по шариату выкуп] и выплата ему [простившему] (должна быть произведена) лучшим образом [без задержки и убавления]. Это [выкуп и дозволенность прощения] – облегчение от Господа вашего и милость (и убийце и родственникам убитого); а кто преступит после этого [если после прощения или взятия выкупа убьёт убийцу, или же если убийца не выплатит выкуп], (то) для него – мучительное наказание. (178) И для вас в возмездии [в убийстве убийцы за убитого] – (безопасная) жизнь, о, обладающие разумом! – чтобы вы были остерегающимися (убить кого-либо)! (179)», сура «Аль-Бакара»/178-179 аяты."]],[["p","224/5 - Второй аят:"],["p","Всевышний Аллах сказал: «И Мы предписали [вменили в обязанность] им [потомкам Исраила] в ней [в Торе], что душа (убивается) за душу, и глаз (выбивается) за глаз, и нос (отсекается) за нос, и ухо (отрезается) за ухо, и зуб (вырывается) за зуб, и за раны (полагается) отмщение. А кто (из пострадавших) пожертвует это [своё право на месть] как милостыню [откажется от мести], то это (станет) искуплением для него [для части грехов посягнувшего]. А кто не судит по тому, что низвёл Аллах, то такие (являются) беззаконниками», сура «Аль-Маида»/45 аят."],["h2","<b>Раздел: О ранах</b>"],["p","225/6 – Первый аят:"],["p","Всевышний Аллах сказал: «И Мы предписали [вменили в обязанность] им [потомкам Исраила] в ней [в Торе], что душа (убивается) за душу, и глаз (выбивается) за глаз,"],["sc","img/word-92/image87.webp",305,504,"f"],["c","Книга Уголовных Преступлений"],["p","и нос (отсекается) за нос, и ухо (отрезается) за ухо, и зуб (вырывается) за зуб, и за раны (полагается) отмщение. А кто (из пострадавших) пожертвует это [своё право на месть] как милостыню [откажется от мести], то это (станет) искуплением для него [для части грехов посягнувшего]. А кто не судит по тому, что низвёл Аллах, то такие (являются) беззаконниками», сура «Аль-Маида», 45 аят."],["p","226/7 – Второй аят:"],["p","Всевышний Аллах сказал: «Кто же преступает против вас (о, верующие), – то и вы преступайте против него подобно тому, как он преступил против вас», сура «Аль-Бакара»/194 аят."],["h2","<b>Глава: Выкуп за убитого</b>"],["p","227/8 – Первый аят:"],["p","Всевышний Аллах сказал: «И (никак) нельзя [запрещено] верующему убивать (другого) верующего, разве только (если это случится) по ошибке [ненамеренно: по невнимательности, неосторожности и забывчивости]. И кто (если) убьёт верующего по ошибке, то (для него, с целью искупления этого греха, становится обязательным) освобождение верующего раба и (выплата) (установленного по шариату) выкупа, (полностью) вручаемого его семье [наследникам убитого], если (только) они не сделают его как милостыню (для убившего по ошибке, простив ему этот выкуп). А если он [убитый по ошибке] (был) из народа враждебного вам [из страны или племени неверующих] и (при этом) (являлся) верующим (но об этом убийца не знал), то (искуплением в таком случае явится) (только) освобождение верующего раба [выкуп за него не даётся]. А если он [убитый по ошибке] (являлся) из народа, между которым и вами (есть) договор [если убитый являлся неверующим в рамках договора или же находился под защитой верующих], то (искуплением в таком случае явится) (выплата) (установленного по шариату) выкупа, (полностью) вручаемого его семье [наследникам убитого], и освобождение верующего раба. А кто же (из убийц) не найдёт (раба для освобождения), то (он будет обязан соблюдать) пост в течение двух последовательных месяцев как покаяние пред Аллахом. И ведь Аллах знает (кто убил по ошибке) (и) мудрый (в Своих установлениях)!», сура «Ан-Ниса»/92 аят."],["sep",""],["sc","img/word-92/image88.webp",296,503,"f"],["c","Книга Установленных Наказаний"],["h2","<b>Книга Установленных Наказаний (1)</b>"]],[["p","228/1 – Первый аят:"],["p","Всевышний Аллах сказал: «Таковы границы Аллаха [обязательные установления] (которые отделяют дозволенное от запретного), не преступайте же их [границы]», сура «Аль-Бакара»/229 аят."],["p","229/2 – Второй аят:"],["p","Всевышний Аллах сказал: «Это – границы Аллаха, и вы не приближайтесь к ним [к этим запретам]», сура «Аль-Бакара»/187 аят."],["h2","<b>Глава: Наказание за прелюбодеяние</b>"],["p","230/3 – Первый аят:"],["p","Всевышний Аллах сказал: «И не приближайтесь к прелюбодеянию [избегайте даже причин, которые могут привести к нему], ведь это [прелюбодеяние] – мерзость [один из наихудших деяний] и скверно как путь!», сура «Аль-Исра»/32 аят."],["p","231/4 – Второй аят:"],["p","Всевышний Аллах сказал: «Прелюбодейку и прелюбодея (которые ещё прежде не состояли в супружестве) – высеките каждого из них сто раз плетью. И пусть не овладевает вами жалость [сострадание] к ним двоим [прелюбодеям] в (исполнении) закона Аллаха (так, чтобы оставить это наказание или произвести его мягче), если вы веруете в Аллаха и в Последний день. И пусть присутствует при наказании их двоих группа верующих (чтобы это послужило порицанием для одних, предупреждением и назиданием для других)», сура «Ан-Нур»/2 аят."],["p","(1) Общее число аятов, которые Ибн Касим приводит в книге Установленных Наказаний - 25 аятов."],["sc","img/word-92/image89.webp",293,504,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","232/5 – Третий аят:"],["p","Всевышний Аллах сказал: «То им – половина того, что (полагается) свободным (женщинам), из наказания», сура «Ан-Ниса»/25 аят."],["h2","<b>Раздел: Наказание за гомосексуализм</b>"],["p","233/6 – Первый аят:"],["p","Всевышний Аллах сказал: «И (также отправили Мы) (пророка) Лута. Вот он сказал своему народу: «Неужели вы будете творить мерзость, в которой никто из миров вас не опередил? [Никакое творение до вас не совершало подобное.] (80) Поистине, вы однозначно приходите по страсти к мужчинам [имеете с ними близость] вместо женщин. Да, вы – люди, вышедшие за предел!», сура «Аль-Аараф»/80-81 аяты."]],[["p","234/7 – Второй аят:"],["p","Всевышний Аллах сказал: «И Мы сделали верх его [их селения] низом [перевернули его] и обрушили на них камни из обожжённой глины», сура «Аль-Хиджр»/74 аят."],["h2","<b>Глава: О наказании за навет</b>"],["p","235/8 - Первый аят:"],["p","Всевышний Аллах сказал: «А те, которые бросают (обвинение в совершении прелюбодеяния) в целомудренных [супружески честных] (женщин) (и также целомудренных мужчин), а потом не приведут четырех (справедливых) свидетелей (которые видели прелюбодеяние), – высеките их восьмидесятью ударами плетью и не принимайте от них свидетельства никогда; (так как) они – непокорные, (4) кроме тех, которые покаялись после этого (и сожалели о содеянном) и уладили (своё деяние). И, поистине, Аллах – прощающий (и) милосердный! (5)», сура «Ан-Нур»/4-5 аяты."],["sc","img/word-92/image90.webp",296,503,"f"],["c","Книга Установленных Наказаний"],["p","236/9 – Второй аят:"],["p","Всевышний Аллах сказал: «Поистине, те, которые бросают (обвинение в совершении прелюбодеяния) в целомудренных [супружески честных], непомышляющих (о прелюбодеянии), верующих (женщин), – прокляты  они [ложно обвиняющие] в (этом) мире и в Вечной жизни! И для них [этих лжецов] – великое наказание (если они не раскаются) (23) в тот день [в День Суда], когда будут свидетельствовать против них [против тех, которые бросали ложное обвинение] их языки, их руки и их ноги о том, что они делали. (24) В тот день [в День Суда] воздаст им Аллах в полной мере по их истинной [справедливой] заслуге, и они узнают, что Аллах есть Истинный [то, что всё от Аллаха является истиной] (и) Явный! (25)», сура «Ан-Нур»/23-25 аяты."],["h2","<b>Глава: Наказание за употребление спиртного</b>"],["p","237/10 – Первый аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Поистине, опьяняющие [всё, что затмевает разум], азартные игры, жертвенники [камни, где многобожники совершают жертвоприношение], и стрелы(18) [принятие решения по стрелам] (является) мерзостью [скверной] из деяния сатаны [грехом, который он разукрасил]. Сторонитесь же этого, чтобы вы оказались счастливыми! (90) Сатана желает лишь заронить среди вас вражду и ненависть при помощи опьяняющего [всего, что затмевает разум] и азартных игр, и отклонить вас от поминания Аллаха и молитвы. Прекратите ли вы (совершение этого) (после разъяснения вам вреда)? (91)», сура «Аль-Маида»/90-91 аяты."],["h2","<b>Глава: Отсечение (руки) за воровство</b>"]],[["p","238/11 – Первый аят:"],["p","Всевышний Аллах сказал: «А вору и воровке отсекайте (о, обладатели власти) их руки (как это определено в Законе Аллаха) в воздаяние за то, что они приобрели [взяли чужое имущество без права на это], как устрашение от Аллаха (для других). А Аллах – величественный (в Своём владычестве) (и) мудрый (в Своих решениях и повелениях)!», сура «Аль-Маида»/38 аят."],["sc","img/word-92/image91.webp",294,504,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["h2","<b>Глава: Наказание за разбой</b>"],["p","239/12 – Первый аят:"],["p","Всевышний Аллах сказал: «Воздаянием тем, которые воюют против Аллаха и Его посланника и стремятся сеять на земле беспорядок (убивая людей), (будет заключаться) в том, что они должны будут убиты, или распяты, или (чтобы) были отсечены у них руки и ноги накрест, или (чтобы) они были изгнаны из земли [из страны, где совершили злодеяние] (в другую страну, чтобы содержать их в заключении). Это для них – позор в (этом) мире, и для них в Вечной жизни – великое наказание, - (33) кроме тех (из воюющих), которые покаялись прежде, чем вы получили власть над ними. И знайте же (о, верующие), что Аллах – прощающий (и) милосердный! (34)», сура «Аль-Маида»/33-34 аяты."],["h2","<b>Глава: Сражение со сторонниками притеснения</b>"],["p","240/13 – Первый аят:"],["p","Всевышний Аллах сказал: «И если две группы верующих будут сражаться (друг против друга), то примирите их (о, верующие) (призвав их обратиться за решением к Книге Аллаха и Сунне Пророка). Если же один (из них двоих) будет покушаться на другого (после того, как было вынесено решение и не будет доволен им), то сражайтесь против того, который покушается, пока он не вернется к велению Аллаха [к истине]. А если он вернется, то примирите их по справедливости и будьте беспристрастны [строго придерживаясь решения Аллаха и затем Его посланника и не отдавая предпочтений кому-либо]: поистине, Аллах любит беспристрастных! (9) Поистине, верующие – братья [в любых вопросах верующие возвращаются к одной основе – Вере]. Так улаживайте же (отношения) (даже уже) между двумя вашими братьями (и тем более примиряйте, когда спорящих и враждующих больше) и остерегайтесь Аллаха (во всех ваших делах), – может быть, вы будете одарены милосердием (Аллаха). (10)», сура «Аль-Худжурат/9-10 аяты."]],[["p","241/14 – Второй аят:"],["p","Всевышний Аллах сказал: «О вы, которые уверовали! Повинуйтесь Аллаху и повинуйтесь посланнику и обладателям власти среди вас (в том, что не является ослушанием Аллаха)», сура «Ан-Ниса»/59 аят."],["sc","img/word-92/image92.webp",295,503,"f"],["c","Книга Установленных Наказаний"],["h2","<b>Глава: Шариатское положение вероотступника</b>"],["p","242/15 – Первый аят:"],["p","Всевышний Аллах сказал: «А если кто из вас (о, верующие) отойдёт от своей Веры [станет неверующим] и умрёт неверным, у таких – тщетны [пропадут] их деяния в (этом) мире и в Вечной жизни! И такие  – обитатели Огня, и они в нём вечно пребудут!», сура «Аль-Бакара»/217 аят."],["p","243/16 – Второй аят:"],["p","Всевышний Аллах сказал: «Поистине, Аллах не прощает (без полного покаяния), когда Ему придают сотоварищей [когда кого-либо равняют Ему], но прощает то, что меньше этого [другие грехи, кроме многобожия и неверия], кому пожелает. А кто придаёт Аллаху сотоварищей [совершает многобожие], тот измыслил великий грех», сура «Ан-Ниса»/48 аят."],["p","244/17 – Третий аят:"],["p","Всевышний Аллах сказал: «Ведь тот, кто придаёт Аллаху сотоварищей [служит и поклоняется кому-либо ещё, кроме Него], тому Аллах запретил (вхождение в) Рай. И (конечным) пристанищем для него (будет) Огонь [Ад], и не (будет) у притеснителей помощников (которые спасли бы их от адского наказания)!», сура «Аль-Маида»/72 аят."],["p","245/18 – Четвертый аят:"],["p","Всевышний Аллах сказал: «Поистине, те [иудеи, христиане и другие], которые проявляют неверие в Аллаха и Его посланников и желают сделать разделение между Аллахом и Его посланниками [веровать в Аллаха и отвергать Его посланников], и говорят: «Мы веруем в одних (пророков) и не веруем в других». И хотят они найти между этим (некий) (средний) путь, - (150) такие – они в действительности (являются) неверующими. И приготовили Мы неверующим унизительное наказание! (151)», сура «Ан-Ниса»/150-151 аяты."],["sc","img/word-92/image93.webp",294,505,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"]],[["p","246/19 - Пятый аят:"],["p","Всевышний Аллах сказал: «Это – за то, что они возненавидели то, что ниспослал Аллах [Коран], и Он сделает тщетными их деяния», сура «Мухаммад»/9 аят."],["p","247/20 – Шестой аят:"],["p","Всевышний Аллах сказал: «А если ты (о, Пророк) спросишь их [лицемеров], они, конечно же, скажут: «Мы только погружались (в беседы) и забавлялись [это были лишь слова, и мы ничего плохого не подразумевали]». Скажи: «Неужели вы насмехались над Аллахом, Его знамениями и Его посланником?» (65) Не оправдывайтесь (о, лицемеры) (так как ваши оправдания бесполезны)! Вот уже вы стали неверными (произнеся эту насмешку), после вашей веры. Если Мы простим одной партии из вас (которая попросит прощения и обратится к Аллаху с покаянием), то накажем (другую) партию за то, что они были бунтарями (упорствуя в своих греховных словах и насмешках). (66)», сура «Ат-Тауба»/65-66 аяты."],["p","248/21 – Седьмой аят:"],["p","Всевышний Аллах сказал: «И из Его знамений (которые указывают Его рабам на Его величие, могущество и власть) – ночь и день [смена ночи и дня], солнце и луна [их подчинённость]. Не делайте поклоны ниц ни солнцу, ни луне, а делайте поклоны ниц (только) Аллаху, Который сотворил их, если вы Ему поклоняетесь [исполняете Его Слово, повинуетесь Ему]! (37) А если они [эти многобожники] проявят высокомерие (по отношению к тому, чтобы делать поклоны ниц перед Аллахом), то те, которые у Господа твоего [ангелы] (не проявляют высокомерия в этом и), восславляют Его и ночью и днём, и они не испытывают скуки (от этого) (38)», сура «Фуссылят»/37-38 аяты."],["p","239/22 – Восьмой аят:"],["p","Всевышний Аллах сказал: «А те, которые взяли покровителей [божества], кроме Него (говорят): «Мы поклоняемся им [божествам] только, чтобы они приблизили нас к Аллаху как можно ближе». Поистине, Аллах рассудит между ними [между верующими (единобожниками) и неверующими (многобожниками)] (в День Суда) относительно того,"],["sc","img/word-92/image94.webp",296,503,"f"],["c","Книга Установленных Наказаний"]],[["p","в чём они разногласят [относительно того, кому должны быть посвящено поклонение]! Поистине, Аллах не ведёт (истинным путём) того, кто лжёт  (возводя на Аллаха ложь), (и) неверен (отвергая Его знамения и доказательства)», сура «Аз-Зумар»/3 аят."],["p","250/23 – Девятый аят:"],["p","Всевышний Аллах сказал: «Поистине, те, которые уверовали, а потом (обратно) стали неверующими, потом (снова) уверовали, и затем (опять) стали неверными [колеблющиеся в сомнениях], потом усилили неверие [умерли на неверии], – не таков Аллах, чтобы простить им и не (таков Он, чтобы) наставить их на (истинный) путь. (137) Обрадуй (о, Пророк) лицемеров (вестью) о том, что им (уготовано) мучительное наказание, - (138) тех, которые берут неверующих покровителями себе, вместо верующих! Не ищут ли они [лицемеры] у них [у неверующих] величия? Поистине же, всё величие у Аллаха! (139) И (ведь) уже Аллах низвёл вам (о, верующие) в Книге [в Коране], что когда вы услышите, как (как какие-либо люди) отвергают знамения Аллаха и насмехаются над ними, то не сидите (вместе) с ними, пока они не перейдут на другой рассказ [пока не изменят тему разговора]. Поистине, вы в таком случае будете подобны им. Поистине, Аллах соберёт лицемеров и неверных всех в Геенне [Аду]! (140) (Лицемеры) – это те, которые выжидают, что будет с вами (о, верующие). Если вам будет победа от Аллаха, они говорят: «Разве мы не были с вами?» А если выпадет неверующим доля (победы и трофеев), они [лицемеры] говорят (им): «Разве мы не старались помочь вам и не удерживали [защищали] вас от верующих?» А Аллах же рассудит между вами в День Воскрешения. И никогда Аллах не устроит неверующим пути против верующих [не даст победу неверующим] (если верующие будут твёрдо держаться Веры и полностью повиноваться Аллаху и Его посланнику). (141) Поистине, лицемеры пытаются обмануть Аллаха (внешне показывая веру, и скрывая неверие в душе), тогда как Он (Сам) обманет их (в День Воскрешения)! А когда они [лицемеры] встают на молитву, то встают ленивыми, (молясь) (лишь) для вида пред людьми, и вспоминают Аллаха, только мало, (142) колеблясь (в сомнениях) между этим [между Верой и неверием]. Они не примыкают ни к этим [к верующим], ни к этим [к неверующим]. И (ведь) если кого Аллах введёт в заблуждение (оставив без Своего содействия в наставлении), то для того ты не найдешь пути! (143) О вы, которые уверовали!"],["sc","img/word-92/image95.webp",294,504,"f"]],[["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","Не берите неверующих себе покровителями [сторонниками] вместо верующих. Разве вы хотите (своей любовью к неверующим) дать Аллаху ясный довод против вас (на то, что вы не правдивы в своей вере) (144) Поистине, лицемеры – в (самом) нижнем слое Огня [Ада] {Ад состоит из семи слоев}, и никогда ты (о, Пророк) не найдешь для них помощника (который смог бы защитить их от злейшего пристанища) (145) Кроме тех, которые покаялись (перед Аллахом) [оставили неверие лицемерия] и исправили (те злодеяния, которые они совершали скрытно и явно), и ухватились за (веру и Закон) Аллаха и сделали свою веру исключительным только ради Аллаха [поклонялись и служили только Аллаху, и только ради Его довольства]! Вот такие – (вместе) с верующими (в этом мире и в Вечной жизни), и (ведь) Аллах одарит верующих великой наградой! (146)», сура «Ан-Ниса»/138-146 аяты."],["p","251/24 – Десятый аят:"],["p","Всевышний Аллах сказал: «Но они оба [те два ангела] не обучали никого (колдовству), пока не говорили: «Поистине, мы – искушение, не становись же неверным (изучая колдовство и подчиняясь шайтанам)!» И (люди) учились от них [от тех двух ангелов], чем разлучать мужа от жены. Но они [колдуны] не смогут навредить этим никому без дозволения Аллаха (на то). И обучались они [колдуны] тому, что наносило вред им (самим же) и не приносило пользы им. (И шайтаны принесли колдовство иудеям, и это распространилось среди них настолько, что они предпочитали колдовство даже больше, нежели книгу Аллаха.) И они [иудеи] знали, что тот, кто приобретал [выбирал] это [колдовство], – (то) нет ему в Вечной жизни никакой доли (блага). И, конечно же, как скверно [плохо] то [колдовство и неверие], за что они продали свои души, – если бы они знали! (102) А если бы они [иудеи] уверовали бы (истинно) и остерегались бы (наказания Аллаха) (исполняя Его повеления и сторонясь того, что Он запретил), то награда (за это) от Аллаха (была бы для них) лучше (чем то, что они выбрали для себя), – если бы (только) они знали! (103)», сура «Аль-Бакара»/102-103 аяты."],["p","252/25 – Одиннадцатый аят:"],["p","Всевышний Аллах сказал: «Кто станет неверующим в Аллаха после своей веры – кроме (лишь) того, кто был принуждён (сказать слова неверия), а (в то время) сердце его (было) спокойным в Вере [в душе он был полон Веры и убеждённости]», сура «Ан-Нахль»/106 аят."],["sc","img/word-92/image96.webp",296,505,"f"],["c","Книга Пищевых продуктов"],["h2","<b>Книга Пищевых продуктов (1)</b>"]],[["p","253/1 – Первый аят:"],["p","Всевышний Аллах сказал: «(Только) Он [Аллах] – Тот, Который сотворил вам всё, что на земле [все блага, которыми вы пользуетесь]», сура «Аль-Бакара»/29 аят."],["p","254/2 – Второй аят:"],["p","Всевышний Аллах сказал: «О, люди! Питайтесь тем (из удела дарованного Аллахом), что на земле, (что является) дозволенным [чистым от скверны], благим [полезным, а не вредным], и не следуйте по стопам сатаны (в ослушании Аллаху, а также называя что-то без знания дозволенным или запретным, и также совершая нововведения в Закон Аллаха), – ведь он [сатана] для вас враг явный! (168) (И) приказывает он [сатана] вам только плохое [малые грехи] и мерзость [большие грехи] и чтобы вы говорили на Аллаха то, чего не знаете [измышляли ложь против Аллаха без знания]. (169)», сура «Аль-Бакара»/168-169 аяты."],["p","255/3 – Третий аят:"],["p","Всевышний Аллах сказал: «Дозволена вам (о, верующие) охота в море (на живые морские животные) и еда из него [то, что добыто уже умершим] в пользование вам и путникам», сура «Аль-Маида»/96 аят."],["p","256/4 – Четвертый аят:"],["p","Всевышний Аллах сказал: «Объявляет дозволенным им блага [благие виды пищи, питья и супружества] и объявляет запретным им мерзости [мерзкие виды еды и супругов],"],["p","(1) Общее число аятов, которые привел Ибн Касим в книге Пищи – 32 аята."],["sc","img/word-92/image97.webp",325,506,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","снимает с них их бремя и оковы, которые были на них [облегчает те положения, которые были раньше(3)], – вот те, которые уверовали в него [в Мухаммада], и поддерживали его, и помогали ему, и последовали за светом, который ниспослан с ним [в Коран], это – те, обретшие счастье (в этом мире и в Вечной жизни)!», сура «Аль-Аараф»/157 аят."],["p","257/5 – Пятый аят:"],["p","Всевышний Аллах сказал: «Скажи (о, Посланник): «В том, что даётся мне откровением (от Аллаха), я не нахожу запретным для питающегося то, чем он питается, если только это не будет мертвечина [животное, которое умерло, не будучи зарезанным], или вытекшая (из животного) кровь, или мясо свиньи, потому что это – скверна, – или (если это заклание было) непокорностью (Аллаху), (когда животное) было заколото ради (кого-то) кроме Аллаха», сура «Аль-Анаам»/145 аят."],["h2","<b>Раздел: О том, кто был вынужден (съесть запретное)</b>"]],[["p","258/6 – Первый аят:"],["p","Всевышний Аллах сказал: «А кто же (будет) вынужден в голоде (кушать то, что запретил Аллах), а не склоняясь (намеренно) к греху, – то (ведь) поистине Аллах – прощающий (и) милосердный!», сура «Аль-Маида»/3 аят."],["p","259/7 – Второй аят:"],["p","Всевышний Аллах сказал: «Кто же (будет) вынужден (есть в голоде, чтобы не умереть), не проявляя желания и чрезмерства [не испытывая наслаждения и не наедаясь), – то (ведь) Аллах – прощающий (и) милосердный», сура «Ан-Нахль»/115 аят."],["p","260/8 – Третий аят:"],["p","Всевышний Аллах сказал: «И отказывают в подаянии [отказывает даже в таких простых вещах, как ведро, мотыга, котел, и даже в воде и соли]!», сура «Аль-Маун»/7 аят."],["sc","img/word-92/image98.webp",346,510,"f"],["c","Книга Пищевых продуктов"],["h2","<b>Раздел: О (встрече) гостя</b>"],["p","261/9 – Первый аят:"],["p","Всевышний Аллах сказал: «Разве уже дошёл до тебя рассказ [история] о почтенных гостях (пророка) Ибрахима [о почтенных ангелах]? (24) Вот пришли они [ангелы] к нему [к Ибрахиму] и сказали: «Мир!» Сказал он [Ибрахим]: «(И вам) мир! (Вы для меня) люди незнакомые!» (25) И (незаметно) отошёл он [Ибрахим] к своей семье (чтобы приготовить угощение для гостей), и принёс (жареное мясо) жирного телёнка, (26) и приблизил его [угощение] к ним [к гостям], (и) сказал: «Не покушаете ли?» (27), сура «Аз-Зарийат»/24-27 аяты."],["p","262/10 – Второй аят:"],["p","Всевышний Аллах сказал: «Они отдают предпочтение (мухаджирам) пред собой, хотя бы и было у них стеснение [даже если сами они бедны и нуждаются]. И кого (Аллах) защитил от скупости (и жадности), – то такие (будут) обретшими счастье (в этом мире и в Вечной жизни)!», сура «Аль-Хашр»/9 аят."],["h2","<b>Глава: Употребление в пищу мяса дозволенных животных</b>"],["p","263/11 – Первый аят:"],["p","Всевышний Аллах сказал: «Запрещена вам мертвечина(3) [животное, которое умерло, не будучи зарезанным], и (вытекшую из животного) кровь, и мясо свиньи, и то, что было заколото ради (кого-то) кроме Аллаха, и то, что было задушено (или задохнулось), и убитая ударом [что умерло от удара], и погибшее от падения, и забоданная (до смерти), и то, что ел [убил] хищник, – если только вы не успеете зарезать его(4), – и (запрещено) то, что было заколото на жертвенниках (которые установили многобожники)», сура «Аль-Маида»/3 аят."]],[["p","264/12 - Второй аят:"],["p","Всевышний Аллах сказал: «И не ешьте (о, верующие) из того (что было зарезано) то, над чем (при заклании) не было помянуто имя Аллаха: и (ведь) поистине это"],["sc","img/word-92/image99.webp",294,504,"f"],["p","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","[кушать такое мясо] однозначно является непокорностью (Аллаху)! И поистине шайтаны, конечно же, внушают своим сторонникам, чтобы они препирались с вами (говоря, что можно есть мертвечину), а если вы (о, верующие) подчинитесь им (в дозволении мертвечины), (то тогда) поистине вы, однозначно, (станете) многобожниками», сура «Аль-Анам»/121 аят."],["p","265/13 – Третий аят:"],["p","Всевышний Аллах сказал: «Пища тех, кому даровано Писание [мясо, зарезанное иудеями и христианами], разрешается вам», сура «Аль-Маида»/5 аят."],["p","266/14- Четвертый аят:"],["p","Всевышний Аллах сказал: «Дозволена вам (о, верующие) охота в море (на живые морские животные) и еда из него [то, что добыто уже умершим]», сура «Адб-Маида»/96 аят."],["h2","<b>Глава: Охота</b>"],["p","267/15 – Первый аят:"],["p","Всевышний Аллах сказал: «Дозволена вам (о, верующие) охота в море (на живые морские животные) и еда из него [то, что добыто уже умершим] в пользование вам и путникам. Но запрещена вам охота на суше, пока вы (находитесь) в ихраме», сура «Аль-Маида»/96 аят."],["p","268/16 – Второй аят:"],["p","Всевышний Аллах сказал: «А когда вы (после завершения всех обрядов паломничества снова будете) в состоянии дозволенности [выйдете из состояния запрещения (ихрам)], то охотьтесь», сура «Аль-Маида»/2 аят."],["p","269/17 – Третий аят:"],["p","Всевышний Аллах сказал: «Дозволены вам блага [любая разрешённая Аллахом пища]. А (также вам дозволена охота), которой вы научили (прирученных) хищных (животных) [собак, соколов,…], отпуская их (ловить дичь). (И) вы учите их [этих охотничьих животных] тому, чему научил вас Аллах. Ешьте же то, что они [охотничьи животные] схватят для вас, и поминайте (произносите) над этим [когда отпускаете охотничье животное] имя Аллаха."],["sc","img/word-92/image100.webp",295,505,"f"],["c","Книга Пищевых продуктов"]],[["p","И остерегайтесь (наказания) Аллаха (выполняя то, что Он повелел и, сторонясь того, что Он запретил), – поистине, Аллах скор в расчете!», сура «Аль-Маида»/4 аят."],["h2","<b>Глава: Клятвы</b>"],["p","270/1 – Первый аят:"],["p","Всевышний Аллах сказал: «Не взыщет с вас Аллах [не станет наказывать] за пустословие в ваших клятвах [за ненамеренно произнесённую клятву], но взыщет Он с вас (о, верующие) за то, что вы связали клятвы [за намеренную клятву]. Искуплением этого [неисполнения клятвы] (является): накормить десять бедняков средним из того, чем вы кормите свои семьи, или одеть их, или освободить раба. А кто же не найдёт [не будет в состоянии сделать одно из этих трёх видов искупления], то (ему) (будет необходимо соблюдать) пост (в течении) трёх дней», сура «Аль-Маида»/89 аят."],["p","271/19 – Второй аят:"],["p","Всевышний Аллах сказал: «Но взыщет [накажет] Он за то, что приобрели ваши сердца [за ваши намерения]», сура «Аль-Бакара»/225 аят."],["p","272/20 – Третий аят (1):"],["p","Всевышний Аллах сказал: «И не нарушайте клятв после их закрепления!», сура «Ан-Нахль»/91 аят."],["p","273/21 – Четвертый аят:"],["p","Всевышний Аллах сказал: «Клянусь же Господом небес и земли», сура «Аз-Зарийат»/23 аят."],["p","274/22 – Пятый аят:"],["p","Всевышний Аллах сказал: «И поклялись они [эти многобожники] Аллахом», сура «Аль-Анам»/109 аят."],["p","(1) Этот аят отсутствует в экзмепляре толкования книги 3/459."],["sc","img/word-92/image101.webp",294,504,"f"],["c","Полное собрание аятов, на основании которых выносятся шариатские постановления"],["p","275/23 – Шестой аят:"],["p","Всевышний Аллах сказал: «Клянусь Аллахом, (в День Суда) вы непременно будете спрошены о том, что измышляли (против Аллаха)», сура «Ан-Нахль»/56 аят."],["p","276/24 – Седьмой аят:"],["p","Всевышний Аллах сказал: «Скажи (им) (о, Пророк): «Наоборот, клянусь Господом моим, вы однозначно будете воскрешены, потом вам непременно будет сообщено то, что вы совершили (в земной жизни), и это для Аллаха легко», сура «Ат-Тагабун»/7 аят."]],[["p","277/25 – Восьмой аят:"],["p","Всевышний Аллах сказал: «И не делайте (о, верующие), чтобы (имя) Аллаха было предметом ваших клятв [не клянитесь именем Аллаха, что вы не будете делать благодеяние в отношении кого-то(40)], чтобы вам (можно было) проявлять благочестие [совершать благие дела] и остерегаться (совершения плохих дел) и улаживать отношения между людьми. Поистине, Аллах – слышащий, знающий!», сура «Аль-Бакара»/224 аят."],["p","278/26 – Девятый аят:"],["p","Всевышний Аллах сказал: «И пусть не клянутся обладающие достоинством [степенью в Вере и возможностью расходовать] из (числа) вас и достатком [имуществом], (что) не будут давать (милостыни) (и оказывать поддержку имуществом) родственникам», сура «Ан-Нур»/22 аят."],["p","279/27 – Десятый аят:"],["p","Всевышний Аллах сказал: «Поистине, те, которые приобретают за завет с Аллахом (который Он завещал им в книгах, которые ниспосылал их пророкам) и (за) свои клятвы ничтожную цену, – они такие, что нет им никакой доли (благого) в Вечной жизни, и не будет говорить с ними Аллах (о том, что обрадовало бы их), и не посмотрит (Он) на них в День Воскресения (взором милосердия), и не очистит их (от их грехов) [не простит им]; и им (уготовано) мучительное наказание», сура «Аль Имран»/77 аят."],["sc","img/word-92/image102.webp",296,504,"f"],["c","Книга Пищевых продуктов"],["p","280/28 – Одиннадцатый аят:"],["p","Всевышний Аллах сказал: «И клянутся они [лицемеры] ложно (что они являются верующими и что ты – Посланник Аллаха) и (сами) знают (что лгут в том, о чём клянутся)», сура «Аль-Муджадиля»/14 аят."],["h2","<b>Раздел: Об искуплении</b>"],["p","281/29 – Первый аят:"],["p","Всевышний Аллах сказал: «Искуплением этого [неисполнения клятвы] (является): накормить десять бедняков средним из того, чем вы кормите свои семьи, или одеть их, или освободить раба. А кто же не найдёт [не будет в состоянии сделать одно из этих трёх видов искупления], то (ему) (будет необходимо соблюдать) пост (в течении) трёх дней. Это [то, что было перечислено] – искупление ваших клятв, которыми вы поклялись. Охраняйте же ваши клятвы [удерживайтесь от клятв; или исполняйте же, если поклялись; или совершайте искупление]! Так разъясняет Аллах вам Свои знамения, чтобы вы были благодарны (Ему) (за то, что Он наставил вас на истинный путь)!», сура «Аль-Маида»/89 аят."],["h2","<b>Раздел: Об обетах</b>"]]];
